  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g9-st2-2026.1', 9, 'g9_st2', 'Lớp 9 - Trạm 2: Gene, nhiễm sắc thể và di truyền người', 'draft', 'Nội dung soạn theo Bài 41–48 của SGK KHTN 9 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
