  values(v_release_id, 9, 'g9_st2', 10, 4, 'category', 'Phân loại đúng nhóm', 'Vận dụng kiến thức gene, nhiễm sắc thể và phân bào để giải thích truyền đạt thông tin di truyền.', '{"categories":["Tham gia truyền thông tin di truyền","Không mang thông tin di truyền của cha mẹ"],"items":["Gene","Nhiễm sắc thể","Giao tử","Ánh sáng môi trường"],"hint":"Dựa vào kiến thức của ải 10."}'::jsonb, '{"value":[{"name":"Gene","catIndex":0},{"name":"Nhiễm sắc thể","catIndex":0},{"name":"Giao tử","catIndex":0},{"name":"Ánh sáng môi trường","catIndex":1}],"explanation":"Gene thuộc nhóm Tham gia truyền thông tin di truyền; Nhiễm sắc thể thuộc nhóm Tham gia truyền thông tin di truyền; Giao tử thuộc nhóm Tham gia truyền thông tin di truyền; Ánh sáng môi trường thuộc nhóm Không mang thông tin di truyền của cha mẹ."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 9 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 41–48. Gene, nhiễm sắc thể và di truyền người"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 9, 'g9_st2', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Vận dụng kiến thức gene, nhiễm sắc thể và phân bào để giải thích truyền đạt thông tin di truyền.', '{"textWithBlanks":"Sau thụ tinh, [blank] nhận vật chất di truyền từ hai giao tử.","bankWords":["hợp tử","khí khổng","mạch gỗ"],"hint":"Dựa vào kiến thức của ải 10."}'::jsonb, '{"value":"hợp tử","explanation":"Từ đúng là “hợp tử”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 9 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 41–48. Gene, nhiễm sắc thể và di truyền người"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
